{
"response_type": "query",
"sql": "SELECT d.A3 AS region, d.A2 AS district, c.gender, ca.type AS card_type, AVG(t.amount) AS avg_transaction_amount, SUM(t.amount) AS total_spending, d.A11 AS district_avg_salary FROM trans t JOIN account a ON t.account_id = a.account_id JOIN disp dp ON a.account_id = dp.account_id JOIN client c ON dp.client_id = c.client_id JOIN district d ON a.district_id = d.district_id JOIN card ca ON dp.disp_id = ca.disp_id WHERE t.operation = 'VYBER KARTOU' AND strftime('%Y', t.date) = '1998' AND dp.type = 'OWNER' GROUP BY d.A3, d.A2, c.gender, ca.type, d.A11",
"message": null
}

